def one(html):
    return "".join(line.strip() for line in html.splitlines())


def heading(title, aside=""):
    st.markdown(f'<div class="sh"><h2>{title}</h2><span>{aside}</span></div>', unsafe_allow_html=True)


def style(fig, height=440):
    fig.update_layout(template="plotly_dark", paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                      font=dict(family="Titillium Web, sans-serif", color="#ffffff", size=14), height=height,
                      margin=dict(l=8, r=8, t=16, b=8))
    fig.update_xaxes(gridcolor=LINE, zerolinecolor=LINE)
    fig.update_yaxes(gridcolor=LINE, zerolinecolor=LINE)
    return fig


def show(fig):
    st.plotly_chart(fig, width="stretch", config={"displayModeBar": False})


# ---------- thumbnails (small graphics instead of photos) ----------
def thumb_line():
    def pts(d):
        return " ".join(f"{8 + i / (N - 1) * 144:.1f},{92 - v / 450 * 80:.1f}" for i, v in enumerate(d["cumulative"]))
    return '<svg viewBox="0 0 160 100">' + "".join(
        f'<polyline fill="none" stroke="{dc(d["driver"])}" stroke-width="2.5" points="{pts(d)}"/>' for d in DR[:3]) + "</svg>"


def thumb_bars():
    return '<svg viewBox="0 0 160 100">' + "".join(
        f'<rect x="10" y="{10 + i * 17}" width="{t["points"] / TM[0]["points"] * 130:.1f}" height="10" rx="3" fill="{tc(t["team"])}"/>'
        for i, t in enumerate(TM[:5])) + "</svg>"


def thumb_donut():
    import math
    c, a, out = 2 * math.pi * 30, 0.0, ""
    for d in WINS:
        l = d["wins"] / NW * c
        out += (f'<circle cx="80" cy="50" r="30" fill="none" stroke="{dc(d["driver"])}" stroke-width="14" '
                f'stroke-dasharray="{max(l - 2, 1):.1f} {c:.1f}" stroke-dashoffset="{-a:.1f}" transform="rotate(-90 80 50)"/>')
        a += l
    return f'<svg viewBox="0 0 160 100">{out}</svg>'


def thumb_heat():
    out = ""
    for y, d in enumerate(DR[:5]):
        for x, r in enumerate(R):
            p = d["weekend"][x]
            fill = f"rgba(225,6,0,{.15 + .85 * p / 33:.2f})" if p else "#2a2a35"
            out += f'<rect x="{8 + x * 6}" y="{14 + y * 16}" width="5" height="13" rx="1" fill="{fill}"/>'
    return f'<svg viewBox="0 0 160 100">{out}</svg>'


